document.addEventListener('DOMContentLoaded',function(){const core=window.ucpAdminCore||{};const currentTab=core.currentTab||'overview';document.querySelectorAll('.ucp-disclosure').forEach(function(detail,index){if(!detail.id){detail.id='ucp-disclosure-'+currentTab+'-'+index;}
detail.addEventListener('toggle',function(){if(!detail.open||detail.dataset.ucpSingleOpen!=='1')return;const group=detail.closest('[data-ucp-disclosure-group]');if(!group)return;group.querySelectorAll(':scope > .ucp-disclosure[data-ucp-single-open="1"]').forEach(function(sibling){if(sibling!==detail){sibling.open=false;}});});});});